#include <stdio.h>
extern int total;
int total = 0;
static void record(int value) { total += value; }
int main(void) {
    for (int i=0; i<3; ++i) { int x; if(scanf("%d", &x)!=1) return 1; record(x); }
    printf("%d\n", total);
    return 0;
}
